from rdkit import Chem
from rdkit.Chem import AllChem
from rdkit.Geometry import Point3D
from scipy.spatial.transform import Rotation
from scipy.optimize import least_squares
import numpy as np
# top graph benzene A B C D E F, Cp D-G-H-I-E
rw=Chem.RWMol()
for i in range(16):
 a=Chem.Atom('C');
 if i==6:a.SetFormalCharge(-1)
 rw.AddAtom(a)
def bond(r,a,b,o=Chem.BondType.SINGLE):r.AddBond(a,b,o)
for i in range(6):bond(rw,i,(i+1)%6)
for u,v in [(3,6),(6,7),(7,8),(8,4),(8,9),(7,15)]:bond(rw,u,v)
for i in range(9,14):bond(rw,i,i+1)
bond(rw,14,9)
for atom in rw.GetAtoms():
 if atom.GetIdx() in list(range(9,15))+list(range(6)) + [7,8]:atom.SetIsAromatic(True)
for b in rw.GetBonds():
 if b.GetBeginAtomIdx() in [*range(9,15)] and b.GetEndAtomIdx() in [*range(9,15)]:b.SetBondType(Chem.BondType.AROMATIC);b.SetIsAromatic(True)
# let RDKit infer Kekule of indenyl: bond benzene and Cp aromatic set all 0-8 aromatic
for atom in rw.GetAtoms():
 if atom.GetIdx()<9:atom.SetIsAromatic(True)
for b in rw.GetBonds():
 if b.GetBeginAtomIdx()<9 and b.GetEndAtomIdx()<9:b.SetBondType(Chem.BondType.AROMATIC);b.SetIsAromatic(True)
top=rw.GetMol()
try:Chem.SanitizeMol(top);print('TOP:',Chem.MolToSmiles(top))
except Exception as e:print('top sanitize fails',e);raise
# bottom ring spiro: 0 at (191,229); 1 163,210; 2 123,219;3 111,248;4 139,269;5 179,259; 6 231,251;7 259,220;8 241,188;9 201,190; 10 N; 11 Troc carbonyl carbon; 12 carbonyl O; 13 O ester;14 CH2;15 CCl3;16-18 Cl
rw=Chem.RWMol()
for i in range(19):
 s='N' if i==10 else 'O' if i in [12,13] else 'Cl' if i>=16 else 'C'
 a=Chem.Atom(s)
 if i==5:a.SetFormalCharge(1)
 if i==10:a.SetFormalCharge(-1)
 rw.AddAtom(a)
for a,b in [(0,1),(2,3),(4,5),(5,0),(0,6),(6,7),(7,8),(8,9),(9,0),(8,10),(10,11),(11,13),(13,14),(14,15),(15,16),(15,17),(15,18)]:bond(rw,a,b)
for a,b in [(1,2),(3,4),(11,12)]:bond(rw,a,b,Chem.BondType.DOUBLE)
bot=rw.GetMol(); Chem.SanitizeMol(bot);print('BOT:',Chem.MolToSmiles(bot))
# pivalate O carbonyl # 0 C carboxyl; 1 O carbonyl, 2 O anionic; 3 tBu center;4-6 Me
rw=Chem.RWMol()
for i in range(7):
 a=Chem.Atom('O' if i in [1,2] else 'C');
 if i==2:a.SetFormalCharge(-1)
 rw.AddAtom(a)
for a,b in [(0,1),(0,2),(0,3),(3,4),(3,5),(3,6)]:bond(rw,a,b,Chem.BondType.DOUBLE if (a,b)==(0,1) else Chem.BondType.SINGLE)
piv=rw.GetMol();Chem.SanitizeMol(piv)
# embed and MMFF
mols=[top,bot,piv]
for i,m in enumerate(mols):
 m=Chem.AddHs(m);mols[i]=m
 ps=AllChem.ETKDGv3();ps.randomSeed=51+i;ps.maxIterations=500
 result=AllChem.EmbedMolecule(m,ps); print('embed',i,result,len(m.GetAtoms()))
 if result!=0: raise ValueError('embed')
 print('MMFF params',AllChem.MMFFHasAllMoleculeParams(m))
 if AllChem.MMFFHasAllMoleculeParams(m):AllChem.MMFFOptimizeMolecule(m,maxIters=500)
top,bot,piv=mols
# coordinate target map 2D drawing, scale ~ 30px/Angstrom, world x right y upwards. screen X Rh 157, Y 125
px=lambda x,y:np.array([(x-157)/31,(125-y)/31])
# indenyl view screen atoms indexed
pixT={0:(69,44),1:(110,30),2:(148,43),3:(157,59),4:(112,72),5:(78,60),6:(202,72),7:(188,90),8:(125,90),15:(202,105)}
pixB={0:(191,229),1:(163,210),2:(123,219),3:(111,248),4:(139,269),5:(179,259),6:(231,251),7:(259,220),8:(241,188),9:(201,190),10:(217,143),11:(270,114),12:(293,119),13:(272,93),14:(301,84),15:(321,68)}
pixP={0:(83,183),1:(97,142),2:(132,169),3:(49,213),4:(21,194),5:(53,245),6:(24,235)}
# align rotational fit ring sketches only, sometimes distorted stereochemistry so separate fit bottom ring vs substituents and later correct.
def orient(m,targets,fitinds,forcez=None):
 coords=np.array(m.GetConformer().GetPositions()); ids=list(fitinds)
 ref=np.array([px(*targets[j]) for j in ids]); xyz=coords[ids]
 def f(q):
  p=Rotation.from_rotvec(q[:3]).apply(xyz)+q[3:6]; return (p[:,:2]-ref).ravel()
 best=None
 for j in range(40):
  init=np.r_[np.random.default_rng(j).normal(0,2,3),[0,0,0]]
  sol=least_squares(f,init,max_nfev=180);err=np.linalg.norm(sol.fun)
  if best is None or err<best[0]:best=(err,sol.x)
 print('orient error',best[0],'pose',best[1]);q=best[1]
 new=Rotation.from_rotvec(q[:3]).apply(coords)+q[3:6];
 for i,xyz in enumerate(new):m.GetConformer().SetAtomPosition(i,xyz)
 print('residuals',[(j,np.round(new[j,:2]-px(*targets[j]),2)) for j in ids])
 return new
np.random.seed(3)
xyzT=orient(top,pixT,[0,1,2,3,4,5,6,7,8])
xyzB=orient(bot,pixB,list(range(10)))
xyzP=orient(piv,pixP,[0,1,2,3])
# write check prelim with metal Rh at origin and hydrogens
with open('pre.xyz','w') as f:
 f.write(f'{sum(m.GetNumAtoms() for m in mols)+1}\npre structure\n')
 for m in mols:
  for a,xyz in zip(m.GetAtoms(),m.GetConformer().GetPositions()):f.write(f'{a.GetSymbol()} {xyz[0]:.6f} {xyz[1]:.6f} {xyz[2]:.6f}\n')
 f.write('Rh 0 0 0\n')
